Base class for handling DeviceEvents.
Derive from this class and override the void callback(global::System.IntPtr hDevice, string name, global::System.IntPtr hEventData) function to implement your own event handler.
Make sure to destruct the event class before closing the Device, e.g. by calling Dispose() manually or by declaring the handler within a using(){} declaration.


public class MyEventHandler : EventHandlerBase
{
    public MyEventHandler(Device device, string name) : base(device, name) { }

    public override void callback(global::System.IntPtr hDevice, string name, global::System.IntPtr hEventData)
    {
    Variant val = 0;

    if (name == EVENT_ACQUISITION_START_ID || name == cxCam.CX_CAM_EVENT_ACQUISITION_START)
    {
        this.getData(hEventData, cxCam.CX_CAM_EVENT_DATA_TIMESTAMP, val);
        ...
    }
}
